INSERT INTO gost_standard (designation, title, status, notes) VALUES
('ГОСТ 25346', 'Основные нормы взаимозаменяемости. Единая система допусков и посадок. Общие положения, ряды допусков и основных отклонений', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.1, 6.3. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 25348', 'Основные нормы взаимозаменяемости. Единая система допусков и посадок. Ряды допусков, основных отклонений и полей допусков для размеров свыше 3150 мм', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.1. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 30893.1', 'Основные нормы взаимозаменяемости. Общие допуски. Предельные отклонения линейных и угловых размеров с неуказанными допусками', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.1, 6.2 (в т.ч. с поправкой ИУС №8-2018, менявшей запись обозначения). Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 25347', 'Основные нормы взаимозаменяемости. Единая система допусков и посадок. Поля допусков для размеров св. 1 до 500 мм', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.4б. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 25349', 'Основные нормы взаимозаменяемости. Поля допусков размеров деталей из пластмасс', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.4б. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 6636', 'Основные нормы взаимозаменяемости. Нормальные линейные размеры', 'ACTIVE', 'Упоминается в ГОСТ 2.307-2011, п. 6.4а. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ Р 2.308', 'Единая система конструкторской документации. Указание на чертежах допусков формы и расположения поверхностей', 'ACTIVE', 'Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены. ВНИМАНИЕ на расхождение обозначения в источниках: ГОСТ 2.307-2011 (п.6.12а) ссылается на него как «ГОСТ 2.308» (без «Р»), более новый ГОСТ Р 2.109-2023 (п.5.10) — как «ГОСТ Р 2.308». Здесь принято актуальное обозначение с «Р»; ссылки из обоих стандартов ведут на эту запись.'),
('ГОСТ 2.309', 'Единая система конструкторской документации. Обозначения шероховатости поверхностей', 'ACTIVE', 'Упоминается в ГОСТ Р 2.109-2023, п. 5.10. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены. Смежен с ГОСТ 25142-1982 (термины шероховатости), который размечен.'),
('ГОСТ 2.301', 'Единая система конструкторской документации. Форматы', 'ACTIVE', 'Упоминается в ГОСТ Р 2.109-2023, п. 4.6 и ГОСТ Р 2.105-2019, п. 6.3.6. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.'),
('ГОСТ 4784', 'Алюминий и сплавы алюминиевые деформируемые. Марки', 'ACTIVE', 'Упоминается в ГОСТ 17232-2023, п. 4.1 (химический состав марок, включая Д16) и разделе 2. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены. Тот же стандарт указан у материала Д16Т в БД НСИ/seed/seed_data.sql.'),
('ОСТ 1 02504-84', 'Типовые формулировки изложения технических требований на чертежах', 'ACTIVE', 'Отраслевой стандарт авиационной промышленности (введён 01.01.1985, 50 с.). Источник таблиц типовых формулировок ТТ, засеянных в machining_requirement_template справочника metal (БД НСИ/seed/seed_typical_technical_requirements.sql). Пункты в gost_clause не размечены: стандарт состоит из таблиц формулировок, а не из проверяемых утверждений — они живут в справочнике НСИ, где с ними сверяются пункты ТТ чертежа.'),
('ГОСТ 11069', 'Алюминий первичный. Марки', 'ACTIVE', 'Упоминается в ГОСТ 17232-2023, п. 4.1 (химический состав марок первичного алюминия) и разделе 2. Полный текст не входит в БД НСИ/ГОСТ/ — пункты не размечены.');
